package net.hawthorn.dndsheets.client.gui;

import net.hawthorn.dndsheets.Condition;
import net.hawthorn.dndsheets.CreatureType;
import net.hawthorn.dndsheets.DamageTypes;
import net.hawthorn.dndsheets.DndsheetsMod;
import net.hawthorn.dndsheets.network.BrowseActionMessage;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;
import net.minecraftforge.registries.ForgeRegistries;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;

/**
 * <p>The mod's "pick instead of typing" list. One screen, three ways to answer: {@link Mode#SINGLE} (click a
 * row, done), {@link Mode#MULTI} (toggle rows, then Done) and {@link Mode#STATES} (each row cycles through
 * states — off / resistant / vulnerable / immune — for things that carry a value). It answers with the same
 * comma-separated text the forms used to ask you to type, so nothing downstream changes.</p>
 *
 * <p>{@link #request} is the single entry point: it knows which sources the client can list by itself (items,
 * enchantments, conditions, damage and creature types) and which only the server knows (spells, traits,
 * monsters, weapons, magic items, classes) — for those it asks, and {@link #deliver} opens the screen when the
 * answer arrives.</p>
 */
public class ChoiceScreen extends ListPickerScreen {
	public enum Mode { SINGLE, MULTI, STATES }

	public record Option(String id, Component label) {}

	private static final String[] ON_OFF = {"", "on"};
	private static final String[] AFFINITY_STATES = {"", "resistant", "vulnerable", "immune"};

	private final List<Option> options;
	private final Mode mode;
	private final String[] states;
	private final Map<String, Integer> state = new LinkedHashMap<>();
	//The token the field already had for an id ("dndsheets:goblin x4"): kept if the id stays selected.
	private final Map<String, String> tokens = new LinkedHashMap<>();
	private final Consumer<String> onDone;

	private ChoiceScreen(Component title, List<Option> options, Mode mode, String currentCsv, Consumer<String> onDone, Screen parent) {
		super(title, parent);
		this.options = options;
		this.mode = mode;
		this.states = mode == Mode.STATES ? AFFINITY_STATES : ON_OFF;
		this.onDone = onDone;
		for (String raw : currentCsv.split(",")) {
			String token = raw.trim();
			if (token.isEmpty()) continue;
			String id = token.split("[\\s:]")[0];
			tokens.put(id, token);
			int index = 1;
			if (mode == Mode.STATES && token.contains(":")) {
				index = Math.max(1, java.util.Arrays.asList(states).indexOf(token.substring(token.indexOf(':') + 1).trim().toLowerCase(Locale.ROOT)));
			}
			state.put(id, index);
		}
	}

	private record Pending(String source, Mode mode, String current, Consumer<String> onDone) {}

	private static Pending pending;

	/** Opens the right picker for {@code source}; {@code onDone} gets the comma-separated result. */
	public static void request(String source, boolean multi, String current, Consumer<String> onDone) {
		Mode mode = source.equals("DAMAGE_AFFINITY") ? Mode.STATES : multi ? Mode.MULTI : Mode.SINGLE;
		switch (source) {
			case "ITEM" -> ItemPickerScreen.open(item -> true, current, multi, onDone);
			case "ENCHANTMENT" -> {
				List<Option> list = new ArrayList<>();
				ForgeRegistries.ENCHANTMENTS.getEntries().forEach(e ->
					list.add(new Option(e.getKey().location().toString(), Component.translatable(e.getValue().getDescriptionId()))));
				open(source, list, mode, current, onDone);
			}
			case "CONDITION" -> open(source, conditions(), mode, current, onDone);
			case "EFFECT" -> {
				List<Option> list = new ArrayList<>();
				for (String name : new String[] {"poison", "burning", "bleeding"}) list.add(new Option(name, Component.literal(name)));
				list.addAll(conditions());
				open(source, list, mode, current, onDone);
			}
			case "CREATURE_TYPE" -> {
				List<Option> list = new ArrayList<>();
				for (CreatureType type : CreatureType.values()) {
					if (type != CreatureType.UNKNOWN) list.add(new Option(type.name().toLowerCase(Locale.ROOT), Component.literal(type.name().toLowerCase(Locale.ROOT))));
				}
				open(source, list, mode, current, onDone);
			}
			case "DAMAGE_AFFINITY" -> {
				List<Option> list = new ArrayList<>();
				for (String type : DamageTypes.CANONICAL) list.add(new Option(type, Component.literal(type)));
				open(source, list, mode, current, onDone);
			}
			default -> {
				//Only the server has these registries (SPELL, TRAIT, MONSTER, WEAPON, MAGIC_ITEM, CLASS).
				pending = new Pending(source, mode, current, onDone);
				DndsheetsMod.PACKET_HANDLER.sendToServer(new BrowseActionMessage(BrowseActionMessage.Action.LIST_IDS, source));
			}
		}
	}

	private static List<Option> conditions() {
		List<Option> list = new ArrayList<>();
		for (Condition condition : Condition.values()) list.add(new Option(condition.label(), Component.literal(condition.label())));
		return list;
	}

	/** The server's answer to a {@code LIST_IDS} request. */
	public static void deliver(String source, List<String> ids, List<Component> labels) {
		if (pending == null || !pending.source().equals(source)) return;
		List<Option> list = new ArrayList<>();
		for (int i = 0; i < ids.size(); i++) list.add(new Option(ids.get(i), labels.get(i)));
		Pending p = pending;
		pending = null;
		open(source, list, p.mode(), p.current(), p.onDone());
	}

	private static void open(String source, List<Option> options, Mode mode, String current, Consumer<String> onDone) {
		Minecraft minecraft = Minecraft.getInstance();
		minecraft.setScreen(new ChoiceScreen(Component.translatable("gui.dndsheets.choice.title"), options, mode, current, onDone, minecraft.screen));
	}

	@Override
	protected boolean searchable() {
		return true;
	}

	private void finish(String csv) {
		Minecraft.getInstance().setScreen(parent);
		onDone.accept(csv);
	}

	private String result() {
		List<String> out = new ArrayList<>();
		for (Option option : options) {
			int s = state.getOrDefault(option.id(), 0);
			if (s == 0) continue;
			if (mode == Mode.STATES) out.add(option.id() + ":" + states[s]);
			else out.add(tokens.getOrDefault(option.id(), option.id()));
		}
		//Whatever the field held that this list doesn't offer (a hand-typed id, an id from a pack not loaded) is kept.
		for (Map.Entry<String, String> extra : tokens.entrySet()) {
			boolean known = options.stream().anyMatch(o -> o.id().equals(extra.getKey()));
			if (!known) out.add(extra.getValue());
		}
		return String.join(", ", out);
	}

	@Override
	protected void buildRows() {
		if (mode != Mode.SINGLE) addRow(Component.translatable("gui.dndsheets.choice.done"), b -> finish(result()));
		for (Option option : options) {
			addRow(rowLabel(option), b -> {
				if (mode == Mode.SINGLE) {
					finish(option.id());
					return;
				}
				state.put(option.id(), (state.getOrDefault(option.id(), 0) + 1) % states.length);
				this.rebuildWidgets();
			});
		}
	}

	private Component rowLabel(Option option) {
		int s = state.getOrDefault(option.id(), 0);
		if (mode == Mode.SINGLE) return option.label();
		String mark = mode == Mode.STATES ? (s == 0 ? "" : " — " + states[s]) : "";
		return Component.literal(mode == Mode.MULTI ? (s == 0 ? "[ ] " : "[x] ") : "").append(option.label()).append(mark);
	}
}

package net.hawthorn.dndsheets.client.gui;

import net.hawthorn.dndsheets.client.gui.components.TomeButton;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraftforge.registries.ForgeRegistries;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Predicate;

/**
 * <p>Icon grid to pick a registered item (JEI-style: search, scroll, hover for the tooltip, click to choose)
 * instead of typing its id. Deliberately generic: it knows nothing about who asked — the caller passes what
 * to do with the pick ({@code onPick} gets the registry id, e.g. {@code minecraft:iron_sword}) and an
 * optional filter, so any screen that needs an item can reuse it.</p>
 *
 * <p>Single mode answers on the first click. Multi mode toggles items (highlighted) and answers with the
 * comma-separated list when "Done" is pressed; whatever the field already held that isn't a plain item id
 * ("minecraft:arrow x20") is kept as written while it stays selected.</p>
 */
public class ItemPickerScreen extends Screen {
	private static final int CELL = 20;
	private static final int TOP = 56;

	private final Screen parent;
	private final Consumer<String> onPick;
	private final boolean multi;
	private final List<ItemStack> all = new ArrayList<>();
	//id -> the text the field had for it (or the bare id), in the order they were chosen.
	private final Map<String, String> selected = new LinkedHashMap<>();
	private List<ItemStack> shown = new ArrayList<>();
	private EditBox search;
	private String lastQuery = "";
	private int scrollRows = 0;
	private int columns, visibleRows;

	private ItemPickerScreen(Screen parent, Predicate<Item> filter, String currentCsv, boolean multi, Consumer<String> onPick) {
		super(Component.translatable("gui.dndsheets.item_picker.title"));
		this.parent = parent;
		this.onPick = onPick;
		this.multi = multi;
		for (Item item : ForgeRegistries.ITEMS) {
			if (item != Items.AIR && filter.test(item)) all.add(new ItemStack(item));
		}
		if (multi) {
			for (String raw : currentCsv.split(",")) {
				String token = raw.trim();
				if (!token.isEmpty()) selected.put(token.split("\\s+")[0], token);
			}
		}
	}

	/** Single pick over the current screen; "Back"/Escape returns to it without picking. */
	public static void open(Consumer<String> onPick) {
		open(item -> true, "", false, onPick);
	}

	public static void open(Predicate<Item> filter, Consumer<String> onPick) {
		open(filter, "", false, onPick);
	}

	/** {@code currentCsv} is what the field holds now; with {@code multi} the answer is the new comma-separated list. */
	public static void open(Predicate<Item> filter, String currentCsv, boolean multi, Consumer<String> onPick) {
		Minecraft minecraft = Minecraft.getInstance();
		minecraft.setScreen(new ItemPickerScreen(minecraft.screen, filter, currentCsv, multi, onPick));
	}

	@Override
	protected void init() {
		int gridWidth = Math.min(this.width - 40, CELL * 14);
		columns = Math.max(1, gridWidth / CELL);
		visibleRows = Math.max(1, (this.height - TOP - 24) / CELL);

		search = new EditBox(this.font, (this.width - gridWidth) / 2, 32, gridWidth, 18, Component.translatable("gui.dndsheets.common.search"));
		search.setHint(Component.translatable("gui.dndsheets.common.search_hint"));
		search.setValue(lastQuery);
		search.setResponder(text -> {
			lastQuery = text;
			scrollRows = 0;
			applyFilter();
		});
		this.addRenderableWidget(search);
		this.setInitialFocus(search);
		this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.common.back"), b -> this.onClose(), 8, 8, 60, 18));
		if (multi) {
			this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.choice.done"), b -> {
				Minecraft.getInstance().setScreen(parent);
				onPick.accept(String.join(", ", selected.values()));
			}, this.width - 68, 8, 60, 18));
		}
		applyFilter();
	}

	private void applyFilter() {
		String query = lastQuery.trim().toLowerCase(Locale.ROOT);
		shown = new ArrayList<>();
		for (ItemStack stack : all) {
			if (query.isEmpty()
				|| idOf(stack).contains(query)
				|| stack.getHoverName().getString().toLowerCase(Locale.ROOT).contains(query)) {
				shown.add(stack);
			}
		}
	}

	private static String idOf(ItemStack stack) {
		return ForgeRegistries.ITEMS.getKey(stack.getItem()).toString();
	}

	private int gridLeft() {
		return (this.width - columns * CELL) / 2;
	}

	private int maxScroll() {
		return Math.max(0, (shown.size() + columns - 1) / columns - visibleRows);
	}

	/** Index into {@code shown} under the mouse, or -1. */
	private int cellAt(double mouseX, double mouseY) {
		int col = (int) Math.floor((mouseX - gridLeft()) / CELL);
		int row = (int) Math.floor((mouseY - TOP) / CELL);
		if (mouseX < gridLeft() || col >= columns || mouseY < TOP || row >= visibleRows) return -1;
		int index = (scrollRows + row) * columns + col;
		return index < shown.size() ? index : -1;
	}

	@Override
	public boolean mouseClicked(double mouseX, double mouseY, int button) {
		int index = cellAt(mouseX, mouseY);
		if (index >= 0 && button == 0) {
			String id = idOf(shown.get(index));
			if (multi) {
				if (selected.remove(id) == null) selected.put(id, id);
			} else {
				//Back to the caller first, then the pick: the callback usually edits a field of that screen.
				Minecraft.getInstance().setScreen(parent);
				onPick.accept(id);
			}
			return true;
		}
		return super.mouseClicked(mouseX, mouseY, button);
	}

	@Override
	public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
		scrollRows = Math.max(0, Math.min(maxScroll(), scrollRows - (int) Math.signum(delta)));
		return true;
	}

	@Override
	public void tick() {
		search.tick();
	}

	@Override
	public void onClose() {
		Minecraft.getInstance().setScreen(parent);
	}

	@Override
	public boolean isPauseScreen() {
		return false;
	}

	@Override
	public void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTicks) {
		this.renderBackground(guiGraphics);
		int left = gridLeft() - 6;
		GuiStyle.panel(guiGraphics, left, 4, this.width - left, TOP + visibleRows * CELL + 6);
		guiGraphics.drawCenteredString(this.font, this.title, this.width / 2, 12, GuiStyle.TITLE_COLOR);

		int hovered = cellAt(mouseX, mouseY);
		for (int i = 0; i < visibleRows * columns; i++) {
			int index = scrollRows * columns + i;
			if (index >= shown.size()) break;
			int x = gridLeft() + (i % columns) * CELL;
			int y = TOP + (i / columns) * CELL;
			boolean picked = multi && selected.containsKey(idOf(shown.get(index)));
			guiGraphics.fill(x, y, x + CELL - 1, y + CELL - 1, picked ? 0xAA4F9B46 : index == hovered ? 0x66FFD9A0 : 0x44000000);
			guiGraphics.renderItem(shown.get(index), x + 2, y + 2);
		}
		if (shown.isEmpty()) {
			guiGraphics.drawCenteredString(this.font, Component.translatable("gui.dndsheets.item_picker.empty"), this.width / 2, TOP + 20, GuiStyle.MUTED_COLOR);
		}

		super.render(guiGraphics, mouseX, mouseY, partialTicks);
		if (hovered >= 0) guiGraphics.renderTooltip(this.font, shown.get(hovered), mouseX, mouseY);
	}
}

